const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const cambodia = countries.filter(ee.Filter.eq('ADM0_NAME', 'Cambodia'));
  const laos = countries.filter(ee.Filter.eq('ADM0_NAME', 'Lao PDR')); // Exact name for Laos in FAO/GAUL/2015/level0

  // Check if geometries are found
  if (cambodia.size().getInfo() === 0 || laos.size().getInfo() === 0) {
    console.log("Error: Could not find country geometries for Cambodia or Laos.");
    console.log("D"); // Indicates an issue with data (geometry name)
    return;
  }

  const startDate = '2018-02-03';
  const endDate = '2018-02-04'; // Filter for the whole day of February 3rd

  // 2. Data Acquisition
  const fireCollection = ee.ImageCollection('MODIS/006/MCD14DL')
                           .filterDate(startDate, endDate);

  // Check for C1: Empty Collection
  const collectionSize = fireCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No MODIS active fire data found for February 3, 2018.");
    console.log("C1"); // Empty Collection
    return;
  }
  console.log(`Images found for Feb 3, 2018: ${collectionSize}`);

  // Mosaic the images for the day to get a single image representing all detections.
  // The 'MCD14DL' dataset provides point detections, so we mosaic them to count unique points.
  const dailyFires = fireCollection.mosaic();

  // Define scale for reduction (MCD14DL nominal resolution is 1km)
  const scale = 1000;

  // 3. Processing & Calculation
  // We count the number of detected fire pixels where 'brightness_temperature_31' is available.
  const reducer = ee.Reducer.count();

  // Count fires in Cambodia
  const cambodiaFires = dailyFires.reduceRegion({
    reducer: reducer,
    geometry: cambodia.geometry(),
    scale: scale,
    maxPixels: 1e9
  });

  const cambodiaCount = cambodiaFires.get('brightness_temperature_31').getInfo();

  // Count fires in Laos
  const laosFires = dailyFires.reduceRegion({
    reducer: reducer,
    geometry: laos.geometry(),
    scale: scale,
    maxPixels: 1e9
  });

  const laosCount = laosFires.get('brightness_temperature_31').getInfo();

  // Check for C3: Calculation Failure (None, NaN, or invalid)
  if (cambodiaCount === null || laosCount === null || isNaN(cambodiaCount) || isNaN(laosCount)) {
    console.log("Calculation failed to retrieve fire counts (result is None/NaN).");
    console.log("C3"); // Calculation Failure
    return;
  }

  // Check for C2: No Valid Pixels (means counts are 0, but it's a valid zero)
  if (cambodiaCount === 0 && laosCount === 0) {
    console.log("No active fire detections found in either Cambodia or Laos after processing.");
    // Even though counts are 0, this is a valid comparison, not a C2 situation
    // C2 is usually when *all* pixels are masked out, here 0 is a valid result.
  }

  // 4. Validation & Final Answer
  console.log(`Cambodia active fire detections: ${cambodiaCount}`);
  console.log(`Laos active fire detections: ${laosCount}`);

  if (cambodiaCount > laosCount) {
    console.log("A"); // Yes, Cambodia had more
  } else {
    console.log("B"); // No, Cambodia did not have more (equal or less)
  }
}

